import java.util.Scanner;

public class PD {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = parseInt(sc.next());
        long m = parseInt(sc.next());

        long x1 = Math.min(n, m);
        long x2 = Math.max(n, m);
        long product = x1 * x2;
        long result;

        if (x1 == 1) {
            long[] memo = {0, 1, 2, 3, 2, 1};
            result = product - memo[(int) (x2 % 6)];
        } else if (x1 == 2) {
            if (x2 == 2) {
                result = 0;
            } else if (x2 == 3 || x2 == 7) {
                result = product - 2;
            } else {
                result = product;
            }
        } else {
            result = (product & 1) == 0 ? product : product - 1;
        }

        System.out.println(result);
    }

    private static int parseInt(String s) {
        int result = 0;
        boolean negative = false;
        int i = 0;
        if (s.charAt(0) == '-') {
            negative = true;
            i = 1;
        }
        for (; i < s.length(); i++) {
            result = result * 10 + s.charAt(i) - '0';
        }
        return negative ? -result : result;
    }
}
